/* Shared renderer/picker geometry. Bounds are recorded by the actual draw transform. */
export function transformPoint(m,x,y){return {x:m.a*x+m.c*y+m.e,y:m.b*x+m.d*y+m.f}}
export function recordSceneAsset(ctx,item,rect,alpha=null){const m=ctx.getTransform?.();if(!m||!Number.isFinite(m.a))return;const [x,y,w,h]=rect,corners=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(p=>transformPoint(m,...p));const xs=corners.map(p=>p.x),ys=corners.map(p=>p.y);(ctx.canvas.sceneAssets||=[]).push({...item,corners,bounds:{x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)},matrix:{a:m.a,b:m.b,c:m.c,d:m.d,e:m.e,f:m.f},rect,alpha})}
export function translateSceneAssets(items,x=0,y=0){return (items||[]).map(i=>({...i,corners:i.corners.map(p=>({x:p.x+x,y:p.y+y})),bounds:{...i.bounds,x:i.bounds.x+x,y:i.bounds.y+y},matrix:{...i.matrix,e:i.matrix.e+x,f:i.matrix.f+y}}))}
export function hitSceneAsset(item,x,y){const m=item.matrix,det=m.a*m.d-m.b*m.c;if(Math.abs(det)<1e-8)return false;const dx=x-m.e,dy=y-m.f,u=(m.d*dx-m.c*dy)/det,v=(-m.b*dx+m.a*dy)/det,[rx,ry,w,h]=item.rect;if(u<rx||u>rx+w||v<ry||v>ry+h)return false;if(item.alpha){const a=item.alpha,px=Math.max(0,Math.min(a.width-1,Math.floor((u-rx)/w*a.width))),py=Math.max(0,Math.min(a.height-1,Math.floor((v-ry)/h*a.height)));return a.data[(py*a.width+px)*4+3]>18}return true}
export function sampleKeys(base,age,keys=base.keys||[]){if(!keys.length)return base;const sorted=keys.filter(k=>Number.isFinite(k.at)).slice().sort((a,b)=>a.at-b.at);if(!sorted.length)return base;let a=sorted[0],b=sorted.at(-1);if(age<=a.at)return {...base,...a};if(age>=b.at)return {...base,...b};for(let i=1;i<sorted.length;i++)if(age<=sorted[i].at){a=sorted[i-1];b=sorted[i];break}const q=(age-a.at)/Math.max(.001,b.at-a.at),out={...base};for(const k of Object.keys(a)){if(k==='at')continue;out[k]=typeof a[k]==='number'&&typeof b[k]==='number'?a[k]+(b[k]-a[k])*q:a[k]}return out}
const masks=new WeakMap();export function alphaFor(image){if(!(image?.naturalWidth||image?.width))return null;let cached=masks.get(image);if(cached&&cached.src===(image.src||image._alphaVersion))return cached.mask;try{const c=document.createElement('canvas');c.width=192;c.height=Math.max(1,Math.round(192*(image.naturalHeight||image.height)/(image.naturalWidth||image.width)));const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(image,0,0,c.width,c.height);const mask=x.getImageData(0,0,c.width,c.height);masks.set(image,{src:image.src||image._alphaVersion,mask});return mask}catch{return null}}
export function visiblePixels(image){const mask=alphaFor(image);if(!mask?.data)return null;let left=mask.width,top=mask.height,right=-1,bottom=-1;for(let y=0;y<mask.height;y++)for(let x=0;x<mask.width;x++)if(mask.data[(y*mask.width+x)*4+3]>18){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}if(right<0)return null;const width=right-left+1,height=bottom-top+1,data=new Uint8ClampedArray(width*height*4);for(let y=0;y<height;y++)for(let x=0;x<width;x++)data[(y*width+x)*4+3]=mask.data[((y+top)*mask.width+x+left)*4+3];const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height;return {rect:[left/mask.width*iw,top/mask.height*ih,width/mask.width*iw,height/mask.height*ih],alpha:{width,height,data}}}
